  specialCases: [
    {
      id: 'subjunctive-vs-should',
      title: 'Subjunctive vs Should',
      rule: "Subjunctive va should bilan bir xil ma'no, lekin turli registr:\n\nSUBJUNCTIVE (formal, written):\n  I suggest that he GO now.\n  It is essential that she BE present.\n  They insisted that he LEAVE.\n\nSHOULD + V (less formal):\n  I suggest that he SHOULD go now.\n  It is essential that she SHOULD be present.\n  They insisted that he SHOULD leave.\n\n\uD83D\uDD34 British English: should ko'proq ishlatiladi\n\uD83D\uDD34 American English: subjunctive ko'proq\n\uD83D\uDD34 IELTS/Exam: ikkala variant ham to'g'ri\n\n\uD83D\uDCCC Subjunctive = rasmiy, ixcham\n\uD83D\uDCCC Should + V = kamroq rasmiy, British English",
      mnemonic: "Subjunctive = base verb (no -s). Should + V = less formal. Both are correct.",
      commonMistakes: "I suggest that he goes → I suggest that he go.\nI suggest that he should goes → I suggest that he should go.\nSubjunctive must be base verb!",
      examples: [
        { en: "I recommend that she take the exam early. (subjunctive)", uz: "U imtihonni erta topshirishini tavsiya qilaman." },
        { en: "I recommend that she should take the exam early. (should)", uz: "U imtihonni erta topshirishi kerak deb tavsiya qilaman." },
      ],
      drills: [
        { id: 54173, type: 'fill-blank', instruction: "To'g'ri shakl:", question: 'I suggest that he ___ now.', blanks: ['go'], explanation: "Base verb (go, not goes)" },
        { id: 54174, type: 'error-correction', instruction: "Xatoni toping va to'g'rilang:", question: 'I suggest that he goes now.', errorPart: 'goes', correct: 'go', explanation: "Subjunctive = base verb" },
        { id: 54175, type: 'multiple-choice', instruction: "To'g'ri variantni tanlang:", question: "It's essential that she ___ present.", options: ['is', 'be', 'was', 'being'], correct: 'be', explanation: "Subjunctive → base verb be" },
      ],
    },
    {
      id: 'if-i-were',
      title: 'If I Were vs If I Was',
      rule: "If I were va If I was farqi:\n\nIF I WERE (subjunctive, xayoliy):\n  If I were you, I would go. (I am not you)\n  If I were rich, I would travel. (I am not rich)\n  If she were here, she would help. (she is not here)\n\nIF I WAS (indicative, haqiqiy mumkin):\n  If I was late, I apologize. (maybe I was late)\n  If I was rude, I'm sorry. (maybe I was rude)\n\n\uD83D\uDD34 Farq:\n  Were = xayoliy, haqiqatga to'g'ri kelmaydi\n  Was = haqiqiy, mumkin bo'lgan vaziyat\n\n\uD83D\uDCCC IELTS/Exam: were (subjunctive) ishlatish tavsiya etiladi!\n\uD83D\uDCCC Speaking da was keng tarqalgan, lekin writing da were kerak.",
      mnemonic: "If I were you = subjunctive (unreal). If I was late = indicative (real possibility).",
      commonMistakes: "If I was you → If I were you.\nIf I was rich, I would travel → If I were rich, I would travel. (xayoliy → were)\nIf I were late yesterday, sorry → If I was late yesterday, sorry. (haqiqiy → was)",
      examples: [
        { en: "If I were you, I would apologize immediately.", uz: "Sizning o'rningizda bo'lganimda, darhol kechirim so'ragan bo'lardim." },
        { en: "If I was late for the meeting, I sincerely apologize.", uz: "Agar yig'ilishga kechikkan bo'lsam, chin dildan kechirim so'rayman." },
      ],
      drills: [
        { id: 54176, type: 'fill-blank', instruction: "Were yoki was?", question: "If I ___ you, I would accept. (xayoliy)", blanks: ['were'], explanation: "Were (subjunctive) for unreal" },
        { id: 54177, type: 'fill-blank', instruction: "Were yoki was?", question: "If I ___ late, I apologize. (haqiqiy)", blanks: ['was'], explanation: "Was (indicative) for real possibility" },
        { id: 54178, type: 'multiple-choice', instruction: "To'g'ri variantni tanlang:", question: "She looks as if she ___ tired.", options: ['is', 'was', 'were', 'be'], correct: 'were', explanation: "As if + were (unreal)" },
      ],
    },
  ],
